"""Deterministic refund decision over normalized host facts."""


def decide(state: dict) -> dict:
    facts = state["facts"]
    if facts["damaged"]:
        return {"decision": {"status": "approved", "reason": "damaged"}}
    if not facts["receipt"]:
        return {"decision": {"status": "rejected", "reason": "missing_receipt"}}
    if facts["days"] <= 30:
        return {"decision": {"status": "approved", "reason": "within_window"}}
    return {"decision": {"status": "rejected", "reason": "expired"}}


if __name__ == "__main__":
    for damaged, receipt, days, status, reason in [
        (True, False, 0, "approved", "damaged"),
        (True, False, 365, "approved", "damaged"),
        (True, True, 365, "approved", "damaged"),
        (False, False, 0, "rejected", "missing_receipt"),
        (False, False, 365, "rejected", "missing_receipt"),
        (False, True, 30, "approved", "within_window"),
        (False, True, 31, "rejected", "expired"),
    ]:
        assert decide({"facts": {
            "damaged": damaged, "receipt": receipt, "days": days,
            "clearance": False, "member": False,
        }}) == {"decision": {"status": status, "reason": reason}}

