def decide(state: dict) -> dict:
    facts = state["facts"]
    if facts["clearance"]:
        return {"decision": {"status": "rejected", "reason": "clearance"}}
    if facts["damaged"]:
        return {"decision": {"status": "approved", "reason": "damaged"}}
    if not facts["receipt"]:
        return {"decision": {"status": "rejected", "reason": "missing_receipt"}}
    window = 45 if facts["member"] else 30
    if facts["days"] <= window:
        return {"decision": {"status": "approved", "reason": "within_window"}}
    return {"decision": {"status": "rejected", "reason": "expired"}}


if __name__ == "__main__":
    def check(member, days, status, reason, **overrides):
        facts = dict(clearance=False, damaged=False, receipt=True,
                     member=member, days=days)
        facts.update(overrides)
        assert decide({"facts": facts}) == {
            "decision": {"status": status, "reason": reason}
        }

    check(True, 31, "approved", "within_window")
    check(True, 45, "approved", "within_window")
    check(True, 46, "rejected", "expired")
    check(False, 30, "approved", "within_window")
    check(False, 31, "rejected", "expired")
    check(False, 0, "rejected", "missing_receipt", receipt=False)
    check(True, 45, "rejected", "missing_receipt", receipt=False)
    check(True, 46, "approved", "damaged", damaged=True, receipt=False)
    check(True, 46, "rejected", "clearance", clearance=True,
          damaged=True, receipt=False)

